namespace sv_c8b55539b7ed408cb030ed9ecd3eff17.Models;

public sealed class Recipe
{
    public required int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int PrepTimeMinutes { get; init; }
}

using sv_c8b55539b7ed408cb030ed9ecd3eff17.Models;

namespace sv_c8b55539b7ed408cb030ed9ecd3eff17.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_c8b55539b7ed408cb030ed9ecd3eff17.Models;

namespace sv_c8b55539b7ed408cb030ed9ecd3eff17.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Italian pizza with tomato, mozzarella, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Pasta Carbonara", Description = "Creamy Roman pasta with eggs, pecorino, and guanciale.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-flavored dessert with mascarpone cream.", PrepTimeMinutes = 45 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Chicken Tikka Masala", Description = "Grilled chicken in a rich, spiced tomato-cream sauce.", PrepTimeMinutes = 50 },
            new() { Id = 5, Title = "Palak Paneer", Description = "Fresh spinach curry with soft paneer cheese cubes.", PrepTimeMinutes = 35 },
            new() { Id = 6, Title = "Biryani", Description = "Fragrant basmati rice layered with spiced meat and herbs.", PrepTimeMinutes = 60 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Tacos al Pastor", Description = "Spit-grilled pork tacos with pineapple and cilantro.", PrepTimeMinutes = 40 },
            new() { Id = 8, Title = "Guacamole", Description = "Creamy avocado dip with lime, onion, and jalapeño.", PrepTimeMinutes = 10 },
            new() { Id = 9, Title = "Churros", Description = "Fried dough pastries coated in cinnamon sugar.", PrepTimeMinutes = 30 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@using sv_c8b55539b7ed408cb030ed9ecd3eff17.Models
@using sv_c8b55539b7ed408cb030ed9ecd3eff17.Services

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav class="mb-3" aria-label="Cuisine navigation">
    <a href="/recipes/1?sort=@Sort" class="btn @(CuisineId == 1 ? "btn-primary" : "btn-outline-primary")">Italian</a>
    <a href="/recipes/2?sort=@Sort" class="btn @(CuisineId == 2 ? "btn-primary" : "btn-outline-primary")">Indian</a>
    <a href="/recipes/3?sort=@Sort" class="btn @(CuisineId == 3 ? "btn-primary" : "btn-outline-primary")">Mexican</a>
</nav>

<div class="mb-3">
    <label class="form-label fw-bold">Sort by:</label>
    <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm @(Sort == "newest" ? "btn-secondary" : "btn-outline-secondary")">Newest</a>
    <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm @(Sort == "popular" ? "btn-secondary" : "btn-outline-secondary")">Popular</a>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <div class="d-flex align-items-center gap-2 my-4" role="status">
        <div class="spinner-border spinner-border-sm" aria-hidden="true"></div>
        <span>Loading recipes…</span>
    </div>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="d-flex align-items-center gap-2 mb-3 text-muted" role="status">
            <div class="spinner-border spinner-border-sm" aria-hidden="true"></div>
            <small>Refreshing…</small>
        </div>
    }

    <div class="row row-cols-1 row-cols-md-3 g-3">
        @foreach (var recipe in GetSortedRecipes())
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-muted">
                        <small>Prep time: @recipe.PrepTimeMinutes min</small>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;

    private CancellationTokenSource? _loadCts;

    // Track which cuisine the current/last load was for so we only
    // reload when the cuisine actually changes.
    private int _loadedCuisineId;

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == _loadedCuisineId)
        {
            // Only the sort parameter changed — no data reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load for a previous cuisine.
        await CancelPendingLoadAsync();

        _loadedCuisineId = CuisineId;
        _errorMessage = null;
        _isRefreshing = _recipes is not null;

        var cts = new CancellationTokenSource();
        _loadCts = cts;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // Guard against a stale completion after a newer load started.
            if (cts.Token.IsCancellationRequested)
            {
                return;
            }

            _recipes = result;
            _errorMessage = null;
        }
        catch (OperationCanceledException)
        {
            // Expected when the user navigated to a different cuisine or
            // left the page — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
        {
            return Enumerable.Empty<Recipe>();
        }

        return Sort?.ToLowerInvariant() switch
        {
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes),
            _ => _recipes.OrderByDescending(r => r.Id),
        };
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = null;
    }
}

